CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, nombre text NOT NULL DEFAULT 'Estudiante' CHECK (length(nombre) BETWEEN 1 AND 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY update_profile ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN INSERT INTO public.profiles(id,nombre) VALUES (NEW.id, left(coalesce(nullif(trim(NEW.raw_user_meta_data->>'nombre'),''),'Estudiante'),100)); RETURN NEW; END; $$;
CREATE TRIGGER create_studytrack_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, nombre text NOT NULL CHECK(length(nombre) BETWEEN 1 AND 100), color text NOT NULL DEFAULT '#38a995' CHECK(color ~ '^#[0-9A-Fa-f]{6}$'), meta_semanal_horas numeric NOT NULL DEFAULT 5 CHECK(meta_semanal_horas > 0 AND meta_semanal_horas <= 168), archivada boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.subjects TO authenticated; GRANT ALL ON public.subjects TO service_role;
ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_subjects ON public.subjects FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.study_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, subject_id uuid NOT NULL, fecha date NOT NULL, duracion_minutos integer NOT NULL CHECK(duracion_minutos BETWEEN 1 AND 1440), nota text CHECK(length(nota)<=1000), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(subject_id,user_id) REFERENCES public.subjects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.study_sessions TO authenticated; GRANT ALL ON public.study_sessions TO service_role;
ALTER TABLE public.study_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_sessions ON public.study_sessions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX sessions_user_date ON public.study_sessions(user_id,fecha);
CREATE INDEX sessions_subject ON public.study_sessions(subject_id,user_id);
CREATE TABLE public.exams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, subject_id uuid NOT NULL, titulo text NOT NULL CHECK(length(titulo) BETWEEN 1 AND 150), fecha date NOT NULL, FOREIGN KEY(subject_id,user_id) REFERENCES public.subjects(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.exams TO authenticated; GRANT ALL ON public.exams TO service_role;
ALTER TABLE public.exams ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_exams ON public.exams FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX subjects_owner ON public.subjects(user_id);
CREATE INDEX exams_owner ON public.exams(user_id);
CREATE INDEX exams_subject ON public.exams(subject_id,user_id);